import { App, applicationDefault, getApps, initializeApp } from 'firebase-admin/app';
import { Auth, getAuth } from 'firebase-admin/auth';
import { Firestore, getFirestore } from 'firebase-admin/firestore';
import { Storage, getStorage } from 'firebase-admin/storage';
import dotenv from 'dotenv';

dotenv.config();

const projectId = process.env.FIREBASE_PROJECT_ID || '';
const storageBucket = process.env.FIREBASE_STORAGE_BUCKET || undefined;
const hasExplicitCredentialSource = Boolean(
  process.env.GOOGLE_APPLICATION_CREDENTIALS ||
    process.env.FIREBASE_SERVICE_ACCOUNT_JSON ||
    (process.env.FIREBASE_CLIENT_EMAIL && process.env.FIREBASE_PRIVATE_KEY),
);

function getCredential() {
  if (!hasExplicitCredentialSource && process.env.FIREBASE_USE_APPLICATION_DEFAULT_CREDENTIALS !== 'true') {
    return undefined;
  }

  try {
    return applicationDefault();
  } catch (error) {
    console.error('[FIREBASE] Could not load application default credentials:', error);
    return undefined;
  }
}

const credential = getCredential();

export const isFirebaseConfigured = Boolean(credential && projectId);

let firebaseApp: App | undefined;
if (isFirebaseConfigured) {
  firebaseApp = getApps()[0] || initializeApp({
    credential,
    projectId,
    storageBucket,
  });
}

export const firebaseAdmin: Firestore | null = firebaseApp ? getFirestore(firebaseApp) : null;
export const firebaseAuth: Auth | null = firebaseApp ? getAuth(firebaseApp) : null;
export const firebaseStorage: Storage | null = firebaseApp ? getStorage(firebaseApp) : null;

export function getFirebaseStatus() {
  return {
    configured: isFirebaseConfigured,
    projectId: projectId || null,
  };
}
