import 'dotenv/config';
import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import { apiRouter, startNotificationAndSlotScheduler } from './server/routes';
import { db } from './server/db';
import { ensureFirebaseCategories, loadDatabaseSnapshot, loadPersistedSalons, loadPersistedUsers, saveDatabaseSnapshot } from './server/businessPersistence';
import { getFirebaseStatus } from './server/lib/firebaseAdmin';

async function startServer() {
  const app = express();
  const PORT = Number(process.env.PORT) || 3000;
  const isProduction = process.env.NODE_ENV === 'production';

  const firebaseStatus = getFirebaseStatus();
  console.log(`[FIREBASE] ${firebaseStatus.configured ? `connected to ${firebaseStatus.projectId}` : 'not configured; using in-memory data'}`);

  const restoredState = await loadDatabaseSnapshot(db);
  const persistedSalons = await loadPersistedSalons();
  persistedSalons.forEach((salon) => db.salons.set(salon.id, salon));
  const persistedUsers = await loadPersistedUsers();
  persistedUsers.forEach((user) => db.users.set(user.id, user));
  await ensureFirebaseCategories();
  if (persistedSalons.length > 0) {
    console.log(`[FIREBASE] Loaded ${persistedSalons.length} business snapshot(s)`);
  }
  if (persistedUsers.length > 0) {
    console.log(`[FIREBASE] Loaded ${persistedUsers.length} user record(s)`);
  }
  if (restoredState) {
    console.log('[FIREBASE] Restored application state');
  }
  const configuredOrigins = [
    process.env.APP_URL,
    process.env.FRONTEND_URL,
    process.env.PRODUCTION_FRONTEND_ORIGIN,
    process.env.VITE_DEV_ORIGIN,
    process.env.CAPACITOR_ANDROID_ORIGIN,
    'https://qgo.app',
    'capacitor://localhost',
    process.env.CORS_ORIGINS,
  ]
    .flatMap((value) => (value || '').split(','))
    .map((value) => value.trim().replace(/\/$/, ''))
    .filter(Boolean);

  function isPrivateLanHost(hostname: string) {
    return (
      /^10\./.test(hostname) ||
      /^192\.168\./.test(hostname) ||
      /^172\.(1[6-9]|2\d|3[0-1])\./.test(hostname)
    );
  }

  function isAllowedOrigin(origin?: string) {
    if (!origin) return true;
    const normalized = origin.replace(/\/$/, '');
    if (configuredOrigins.includes(normalized)) return true;

    if (!isProduction) {
      try {
        const { hostname, protocol } = new URL(normalized);
        return (
          (protocol === 'http:' || protocol === 'https:') &&
          (hostname === 'localhost' ||
            hostname === '127.0.0.1' ||
            hostname === '::1' ||
            hostname === '[::1]' ||
            isPrivateLanHost(hostname))
        );
      } catch {
        return false;
      }
    }

    return false;
  }

  // Standard middleware
  app.use((req, res, next) => {
    const origin = req.headers.origin;
    if (isAllowedOrigin(origin)) {
      if (origin) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Vary', 'Origin');
      }
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
    }

    if (req.method === 'OPTIONS') {
      return res.sendStatus(isAllowedOrigin(origin) ? 204 : 403);
    }

    next();
  });
  app.use(express.json({ limit: '50mb' }));
  app.use(express.urlencoded({ limit: '50mb', extended: true }));

  // Health check
  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok', name: 'QGo API', timestamp: new Date().toISOString() });
  });

  // Mount API Router under /api/v1 and /api
  app.use('/api/v1', apiRouter);
  app.use('/api', apiRouter);

  // Start Background Reminder Scheduler
  startNotificationAndSlotScheduler();

  // The API currently mutates the in-memory maps in many route handlers. A
  // periodic snapshot keeps all app data durable without requiring every
  // handler to know about the persistence layer.
  const persistenceTimer = setInterval(() => {
    void saveDatabaseSnapshot(db);
  }, 5000);
  persistenceTimer.unref();

  // Vite middleware for development vs static build in production
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        hmr: process.env.DISABLE_HMR === 'true' ? false : undefined,
      },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`\n  \x1b[32m✔\x1b[0m \x1b[1mQGo App is running!\x1b[0m`);
    console.log(`  \x1b[36m➜\x1b[0m  \x1b[1mLocal:\x1b[0m   \x1b[36mhttp://localhost:${PORT}/\x1b[0m`);
    console.log(`  \x1b[36m➜\x1b[0m  \x1b[1mNetwork:\x1b[0m listening on all interfaces (0.0.0.0:${PORT})\n`);
  });
}

startServer().catch((err) => {
  console.error('Failed to start QGo server:', err);
});
