export const MASTER_CATEGORIES = [
  { id: 'barber_shop', label: '💇 Barber Shop' },
  { id: 'unisex_salon', label: '💇 Unisex Salon' },
  { id: 'beauty_parlour', label: '💅 Beauty Parlour' },
  { id: 'spa', label: '💆 Spa' },
  { id: 'doctor_clinic', label: '🏥 Doctor Clinic' },
  { id: 'dental_clinic', label: '🦷 Dental Clinic' },
  { id: 'diagnostic_lab', label: '🧪 Diagnostic Lab' },
  { id: 'swimming_pool', label: '🏊 Swimming Pool' },
  { id: 'hotel_resort', label: '🏨 Hotel / Resort' },
  { id: 'sports_turf', label: '⚽ Sports / Turf' },
  { id: 'custom_other', label: '📋 Custom / Other' },
] as const;

export function getCategoryLabel(idOrLabel?: string): string {
  if (!idOrLabel) return 'Other';
  const cat = MASTER_CATEGORIES.find((c) => c.id === idOrLabel);
  return cat ? cat.label : idOrLabel;
}

export function isTurfBusiness(category?: string, businessCategoryID?: string, bookingMode?: string): boolean {
  if (bookingMode === 'resource_slot') return true;
  if (businessCategoryID === 'sports_turf' || businessCategoryID === 'swimming_pool') return true;
  if (!category) return false;
  const cat = category.toLowerCase();
  return (
    cat === 'sports_turf' ||
    cat === 'swimming_pool' ||
    cat.includes('turf') ||
    cat.includes('sports arena') ||
    cat.includes('badminton') ||
    cat.includes('cricket') ||
    cat.includes('football') ||
    cat.includes('pool') ||
    cat.includes('box cricket')
  );
}

